function endGame(success,copy){running=false;won=success;lost=!success;titleEl.textContent=success?'Island harmony!':'Try another tide';textEl.textContent=success?`${copy} You gathered every conch on ${stages[currentStage].name} and brought its music home.`:`${copy} The shells on ${stages[currentStage].name} are waiting when you're ready.`;artEl.textContent=success?'🌺 ✨ 🐚':'🌧️ 🦀 🌊';playBtn.textContent='Play again';overlay.classList.remove('hidden');}
function stageUnlocked(index){return Date.now()>=firstVisit+unlockDelays[index];}
function formatWait(ms){const secs=Math.ceil(ms/1000);return `${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;}
function refreshIslandOptions(){islandButtons.forEach((button,index)=>{const unlocked=stageUnlocked(index),small=button.querySelector('small');button.disabled=!unlocked;small.textContent=unlocked?(index===0?'Open now':'Open · ready'):`Opens in ${formatWait(firstVisit+unlockDelays[index]-Date.now())}`;button.classList.toggle('selected',index===selectedStage);});if(!stageUnlocked(selectedStage)){selectedStage=0;refreshIslandOptions();}}
function start(index=selectedStage){if(!stageUnlocked(index)){refreshIslandOptions();return;}selectedStage=index;currentStage=index;const stage=stages[index];shellCount=0;remaining=90;hearts=3;won=lost=paused=false;player.x=480;player.y=542;player.invuln=0;shells=stage.shells.map(([x,y],i)=>({x,y,got:false,phase:i*1.17}));crabs=stage.crabs.map(([x,y],i)=>({x,y,baseX:x,baseY:y,phase:i*2,speed:.8+i*.1}));foundEl.textContent='0';heartsEl.textContent='♥ ♥ ♥';timerEl.textContent='01:30';titleEl.textContent=`${stage.name} awaits`;textEl.textContent=`Find five conch shells on ${stage.name}, dodge the crabs, then return to its seaside shrine.`;artEl.textContent=`${stage.icon} 🐚 🌺`;playBtn.textContent=`Sail to ${stage.name}`;overlay.classList.add('hidden');running=true;last=performance.now();}
refreshIslandOptions();setInterval(refreshIslandOptions,1000);

